import{_ as o,a0 as i,w as l,s as d,I as a,x as e,a1 as t,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 LaTeX 和 TeXstudio 排版文档 | LCTT x X-CMD","titleTemplate":false,"description":"使用 LaTeX 和 TeXstudio 排版文档 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 LaTeX 和 TeXstudio 排版文档 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 LaTeX 和 TeXstudio 排版文档 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20171025 Typeset your docs with LaTeX and TeXstudio on Fedora","title":"使用 LaTeX 和 TeXstudio 排版文档","tag":"202102","desc":""},"relativePath":"202102/20171025 Typeset your docs with LaTeX and TeXstudio on Fedora.md","filePath":"[post].md"}'),c={name:"202102/20171025 Typeset your docs with LaTeX and TeXstudio on Fedora.md"};function u(h,s,m,g,f,b){const n=i("Link");return l(),d("div",null,[s[21]||(s[21]=a("h1",{id:"使用-latex-和-texstudio-排版文档",tabindex:"-1"},[e("使用 LaTeX 和 TeXstudio 排版文档 "),a("a",{class:"header-anchor",href:"#使用-latex-和-texstudio-排版文档","aria-label":"Permalink to “使用 LaTeX 和 TeXstudio 排版文档”"},"​")],-1)),s[22]||(s[22]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2017/07/latex-texstudio-945x400.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("LaTeX 是一个服务于高质量排版的",-1)),t(n,{href:"http://www.latex-project.org/about/"},{default:p(()=>[...s[0]||(s[0]=[e("文档准备系统",-1)])]),_:1}),s[2]||(s[2]=e("。通常用于大量的技术和科学文档的排版。不过，你也可以使用 LaTex 排版各种形式的文档。教师可以编辑他们的考试和教学大纲，学生可以展示他们的论文和报告。这篇文章让你尝试使用 TeXstudio。TeXstudio 是一个便于编辑 LaTeX 文档的软件。",-1))]),s[23]||(s[23]=r(`<h3 id="启动-texstudio" tabindex="-1">启动 TeXstudio <a class="header-anchor" href="#启动-texstudio" aria-label="Permalink to “启动 TeXstudio”">​</a></h3><p>如果你使用的是 Fedora Workstation，请启动软件管理，然后输入 TeXstudio 以搜索该应用程序。然后选择安装并添加 TeXstudio 到你的系统。你可以从软件管理中启动这个程序，或者像以往一样在概览中启动这个软件。</p><p>或者，如果你使用终端，请输入 <code>texstudio</code>。如果未安装该软件包，系统将提示你安装它。键入 <code>y</code> 开始安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ texstudio</span></span>
<span class="line"><span>bash: texstudio: command not found...</span></span>
<span class="line"><span>Install package &#39;texstudio&#39; to provide command &#39;texstudio&#39;? [N/y] y</span></span></code></pre></div><h3 id="你的第一份文档" tabindex="-1">你的第一份文档 <a class="header-anchor" href="#你的第一份文档" aria-label="Permalink to “你的第一份文档”">​</a></h3><p>LaTeX 命令通常以反斜杠 <code>\\</code> 开头，命令参数用大括号 <code>{}</code> 括起来。首先声明 <code>documentclass</code> 的类型。这个例子向你展示了该文档的类是一篇文章。</p><p>然后，在声明 <code>documentclass</code> 之后，用 <code>begin</code> 和 <code>end</code> 标记文档的开始和结束。在这些命令之间，写一段类似以下的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article}</span></span>
<span class="line"><span>\\begin{document}</span></span>
<span class="line"><span>The Fedora Project is a project sponsored by Red Hat primarily to co-ordinate the development of the Linux-based Fedora operating system, operating with the vision that the project &quot;creates a world where free culture is welcoming and widespread, collaboration is commonplace, and people control their content and devices&quot;. The Fedora Project was founded on 22 September 2003 when Red Hat decided to split Red Hat Linux into Red Hat Enterprise Linux (RHEL) and a community-based operating system, Fedora.</span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-05-20-19-15.png" alt=""></p><h3 id="使用间距" tabindex="-1">使用间距 <a class="header-anchor" href="#使用间距" aria-label="Permalink to “使用间距”">​</a></h3><p>要创建段落分隔符，请在文本之间保留一个或多个换行符。下面是一个包含四个段落的示例：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-14-24-42.png" alt=""></p><p>从该示例中可以看出，多个换行符不会在段落之间创建额外的空格。但是，如果你确实需要留出额外的空间，请使用 <code>hspace</code> 和 <code>vspace</code> 命令。这两个命令分别添加水平和垂直空间。下面是一些示例代码，显示了段落周围的附加间距：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article}</span></span>
<span class="line"><span>\\begin{document}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\hspace{2.5cm} The four essential freedoms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\vspace{0.6cm} </span></span>
<span class="line"><span>A program is free software if the program&#39;s users have the 4 essential freedoms:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The freedom to run the program as you wish, for any purpose (freedom 0).\\vspace{0.2cm} </span></span>
<span class="line"><span>The freedom to study how the program works, and change it so it does your computing as you wish (freedom 1). Access to the source code is a precondition for this.\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The freedom to redistribute copies so you can help your neighbour (freedom 2).\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The freedom to distribute copies of your modified versions to others (freedom 3). By doing this you can give the whole community a chance to benefit from your changes. Access to the source code is a precondition for this.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p>如果需要，你也可以使用 <code>noindent</code> 命令来避免缩进。这里是上面 LaTeX 源码的结果：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-17-24-53.png" alt=""></p><h3 id="使用列表和格式" tabindex="-1">使用列表和格式 <a class="header-anchor" href="#使用列表和格式" aria-label="Permalink to “使用列表和格式”">​</a></h3><p>如果把自由软件的四大基本自由列为一个清单，这个例子看起来会更好。通过在列表的开头使用<code>\\begin{itemize}</code>，在末尾使用 <code>\\end{itemize}</code> 来设置列表结构。在每个项目前面加上 <code>\\item</code> 命令。</p><p>额外的格式也有助于使文本更具可读性。用于格式化的有用命令包括粗体、斜体、下划线、超大、大、小和 textsc 以帮助强调文本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article}</span></span>
<span class="line"><span>\\begin{document}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\hspace{2cm} {\\huge The four essential freedoms}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\vspace{0.6cm} </span></span>
<span class="line"><span>\\noindent {\\large A program is free software if the program&#39;s users have the 4 essential freedoms}:</span></span>
<span class="line"><span>\\begin{itemize}</span></span>
<span class="line"><span>\\item \\vspace{0.2cm} </span></span>
<span class="line"><span>\\noindent \\textbf{The freedom to run} the program as you wish, for any purpose \\textit{(freedom 0)}. \\vspace{0.2cm} </span></span>
<span class="line"><span>\\item \\noindent \\textbf{The freedom to study} how the program works, and change it so it does your computing as you wish \\textit{(freedom 1)}. Access to the source code is a precondition for this.\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\item \\noindent \\textbf{The freedom to redistribute} copies so you can help your neighbour \\textit{(freedom 2)}.\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\item \\noindent \\textbf{The freedom to distribute copies of your modified versions} to others \\textit{(freedom 3)}. \\tiny{By doing this you can give the whole community a chance to benefit from your changes.\\underline{\\textsc{ Access to the source code is a precondition for this.}}}</span></span>
<span class="line"><span>\\end{itemize}</span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-17-21-30.png" alt=""></p><h3 id="添加列、图像和链接" tabindex="-1">添加列、图像和链接 <a class="header-anchor" href="#添加列、图像和链接" aria-label="Permalink to “添加列、图像和链接”">​</a></h3><p>列、图像和链接有助于为文本添加更多信息。LaTeX 包含一些高级功能的函数作为宏包。<code>\\usepackage</code> 命令加载宏包以便你可以使用这些功能。</p><p>例如，要使用图像，可以使用命令 <code>\\usepackage{graphicx}</code>。或者，要设置列和链接，请分别使用 <code>\\usepackage{multicol}</code> 和 <code>\\usepackage{hyperref}</code>。</p><p><code>\\includegraphics</code> 命令将图像内联放置在文档中。（为简单起见，请将图形文件包含在与 LaTeX 源文件相同的目录中。）</p><p>下面是一个使用所有这些概念的示例。它还使用下载的两个 PNG 图片。试试你自己的图片，看看它们是如何工作的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article} </span></span>
<span class="line"><span>\\usepackage{graphicx}</span></span>
<span class="line"><span>\\usepackage{multicol}</span></span>
<span class="line"><span>\\usepackage{hyperref}</span></span>
<span class="line"><span>\\begin{document} </span></span>
<span class="line"><span> \\textbf{GNU}</span></span>
<span class="line"><span> \\vspace{1cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> GNU is a recursive acronym for &quot;GNU&#39;s Not Unix!&quot;, chosen because GNU&#39;s design is Unix-like, but differs from Unix by being free software and containing no Unix code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span> Richard Stallman, the founder of the project, views GNU as a &quot;technical means to a social end&quot;. Stallman has written about &quot;the social aspects of software and how Free Software can create community and social justice.&quot; in his &quot;Free Society&quot; book.</span></span>
<span class="line"><span> \\vspace{1cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> \\textbf{Some Projects}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> \\begin{multicols}{2}</span></span>
<span class="line"><span> Fedora</span></span>
<span class="line"><span> \\url{https://getfedora.org}</span></span>
<span class="line"><span> \\includegraphics[width=1cm]{fedora.png}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> GNOME</span></span>
<span class="line"><span> \\url{https://getfedora.org}</span></span>
<span class="line"><span> \\includegraphics[width=1cm]{gnome.png}</span></span>
<span class="line"><span> \\end{multicols} </span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-20-32-32.png" alt=""></p>`,28)),a("p",null,[s[4]||(s[4]=e("这里的功能只触及 LaTeX 功能的表面。你可以在该项目的",-1)),t(n,{href:"https://www.latex-project.org/help/"},{default:p(()=>[...s[3]||(s[3]=[e("帮助和文档站点",-1)])]),_:1}),s[5]||(s[5]=e("了解更多关于它们的信息。",-1))]),s[24]||(s[24]=a("hr",null,null,-1)),a("p",null,[s[7]||(s[7]=e("via: ",-1)),t(n,{href:"https://fedoramagazine.org/typeset-latex-texstudio-fedora/"},{default:p(()=>[...s[6]||(s[6]=[e("https://fedoramagazine.org/typeset-latex-texstudio-fedora/",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=e("作者：",-1)),t(n,{href:"https://fedoramagazine.org/author/yulytas/"},{default:p(()=>[...s[8]||(s[8]=[e("Julita Inca Chiroque",-1)])]),_:1}),s[13]||(s[13]=e(" 选题：",-1)),t(n,{href:"https://github.com/Chao-zhi"},{default:p(()=>[...s[9]||(s[9]=[e("Chao-zhi",-1)])]),_:1}),s[14]||(s[14]=e(" 译者：",-1)),t(n,{href:"https://github.com/Chao-zhi"},{default:p(()=>[...s[10]||(s[10]=[e("Chao-zhi",-1)])]),_:1}),s[15]||(s[15]=e(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...s[17]||(s[17]=[e("Linux中国",-1)])]),_:1}),s[20]||(s[20]=e(" 荣誉推出",-1))])])}const x=o(c,[["render",u]]);export{y as __pageData,x as default};
